// Retail 0x009A5D70: copy the fourteen-word codec dimensions/stride record,
// then derive the packed plane sizes used by the 0x009A5E20 allocator helper.
void __cdecl bfmeInitD70(void *selfRaw, void *sourceRaw)
{
	BfmeInitD70Record *self = (BfmeInitD70Record *)selfRaw;
	unsigned *source = (unsigned *)sourceRaw;

	memcpy(self->m_copied, source, 14 * sizeof(unsigned));

	unsigned width = self->m_copied[0] >> 3;
	unsigned rawHeight = self->m_copied[1];
	unsigned plane = self->m_copied[2];
	unsigned height = rawHeight >> 3;
