	self->m_field84 = pixels;
	unsigned quarterPixels = pixels >> 2;
	self->m_field8C = pixels + quarterPixels * 2;
	unsigned rowBytes = width * 8;
	self->m_field90 = width;
	unsigned chromaSpan = (plane - rowBytes) >> 1;
	register int stride = (int)self->m_copied[3];
	self->m_field78 = (plane + 1) * chromaSpan;
	self->m_field98 = plane;
	self->m_fieldB4 = chromaSpan;
	self->m_field88 = quarterPixels;
	self->m_field7C = (stride + 1) * (chromaSpan >> 1)
		+ (rawHeight + chromaSpan * 2) * plane;
	self->m_field80 = (chromaSpan >> 1) * stride
		+ (rawHeight / 2 + chromaSpan) * stride
		+ (rawHeight + chromaSpan * 2) * plane;
}
